class Solution {
    public int maximumProduct(int[] nums, int k) {
        PriorityQueue<Long> pq = new PriorityQueue<>();
        for (int x : nums) pq.add((long) x);
        while (k-- > 0) pq.add(pq.poll() + 1);
        long ans = 1;
        for (long x : pq) ans = ans * x % 1000000007L;
        return (int) ans;
    }
}

