class Solution {
public:
    int maximumProduct(vector<int>& nums, int k) {
        sort(nums.begin(), nums.end());
        int n = nums.size();
        vector<long long> pref(n + 1, 0);
        for (int i = 0; i < n; i++) pref[i+1] = pref[i] + nums[i];
        auto cost = [&](long long t) {
            int i = lower_bound(nums.begin(), nums.end(), (int)t) - nums.begin();
            return t * i - pref[i];
        };
        long long lo = 0, hi = nums.back() + k;
        while (lo < hi) {
            long long mid = (lo + hi + 1) / 2;
            if (cost(mid) <= k) lo = mid; else hi = mid - 1;
        }
        long long base = (k - cost(lo)) / n, ans = 1;
        for (int x : nums)
            ans = ans * ((x >= lo ? x : lo) + base) % 1000000007;
        return (int)ans;
    }
};

