class Solution {
    public int maximumProduct(int[] nums, int k) {
        Arrays.sort(nums);
        int n = nums.length;
        long[] pref = new long[n + 1];
        for (int i = 0; i < n; i++) pref[i+1] = pref[i] + nums[i];
        long lo = 0, hi = nums[n-1] + (long) k;
        while (lo < hi) {
            long mid = (lo + hi + 1) / 2;
            int i = lowerBound(nums, (int) mid);
            if (mid * i - pref[i] <= k) lo = mid; else hi = mid - 1;
        }
        int i = lowerBound(nums, (int) lo);
        long base = (k - (lo * i - pref[i])) / n, ans = 1;
        for (int x : nums) ans = ans * ((x >= lo ? x : lo) + base) % 1000000007L;
        return (int) ans;
    }
    private int lowerBound(int[] a, int x) {
        int lo = 0, hi = a.length;
        while (lo < hi) { int m = (lo + hi) >>> 1; if (a[m] < x) lo = m + 1; else hi = m; }
        return lo;
    }
}

