var maximumProduct = function(nums, k) {
    const MOD = 1000000007;
    nums.sort((a,b)=>a-b);
    const n = nums.length, pref = [0];
    for (const x of nums) pref.push(pref[pref.length-1] + x);
    const lb = t => { let lo=0, hi=n; while(lo<hi){const m=(lo+hi)>>1; if(nums[m]<t)lo=m+1;else hi=m;} return lo; };
    const cost = t => { const i = lb(t); return t*i - pref[i]; };
    let lo = 0, hi = nums[n-1] + k;
    while (lo < hi) { const mid = Math.floor((lo+hi+1)/2); if (cost(mid) <= k) lo = mid; else hi = mid-1; }
    const base = Math.floor((k - cost(lo)) / n);
    let ans = 1;
    for (const x of nums) ans = ans * ((x >= lo ? x : lo) + base) % MOD;
    return ans;
};
